<?php require __DIR__.'/includes/auth.php';require_admin();require __DIR__.'/config/database.php';$id=(int)($_GET['id']??0);$item=['name'=>'','category_id'=>'','quantity'=>0];if($id){$s=$pdo->prepare('SELECT * FROM items WHERE id=?');$s->execute([$id]);$item=$s->fetch()?:$item;}$categories=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$q=(int)($_POST['quantity']??0);$cat=$_POST['category_id']!==''?(int)$_POST['category_id']:null;if($name===''||$q<0)$error='Enter a name and valid stock values.';else{if($id){$s=$pdo->prepare('UPDATE items SET name=?,category_id=?,quantity=? WHERE id=?');$s->execute([$name,$cat,$q,$id]);}else{$s=$pdo->prepare('INSERT INTO items(name,category_id,quantity) VALUES(?,?,?)');$s->execute([$name,$cat,$q]);}header('Location: inventory.php');exit;}}?>
